import{validate,noteName,parsePitch,renderSVG,projectToPMT}from'./model.mjs';
const $=id=>document.getElementById(id);let project,original,aesthetic=false,mode='score',audioContext=null,voices=[],audioURL=null,playTimer=null;
const KEY='song-drawing-v1';
function message(t,error=false){$('message').textContent=t;$('message').classList.toggle('error',error);}
function safely(fn){return async(...args)=>{try{await fn(...args);}catch(e){message(e.message||String(e),true);}};}
function draft(p){p.provenance={status:'unverified',source:$('source').value,label:'User-supplied or edited note events',limitation:'Notes have been edited or imported. Verify them against the exact score or recording before calling this an accurate transcription.'};return p;}
function jsonText(){return JSON.stringify(project,null,2);}
function saveCurrent(){try{localStorage.setItem(KEY,JSON.stringify(project));}catch{message('This browser could not save locally. Export project JSON to keep your changes.');}}
function revisionList(){let list=[];try{list=JSON.parse(localStorage.getItem(KEY+'-history')||'[]');}catch{}return Array.isArray(list)?list:[];}
function showRevisions(){const el=$('revisions');el.replaceChildren(new Option('Choose a saved revision…',''));revisionList().forEach((r,i)=>el.add(new Option(`${new Date(r.at).toLocaleString()} · ${r.project.title}`,String(i))));}
function table(){const body=$('notes');body.replaceChildren();project.events.forEach((e,i)=>{const tr=document.createElement('tr');const count=document.createElement('td');count.textContent=i+1;tr.append(count);for(const k of['pitch','start','duration']){const td=document.createElement('td'),input=document.createElement('input');input.value=k==='pitch'?noteName(e.pitch):e[k];input.dataset.field=k;input.setAttribute('aria-label',`${k} for note ${i+1}`);if(k!=='pitch'){input.type='number';input.step='any';input.min=k==='start'?'0':'0.001';}td.append(input);tr.append(td);}const sec=document.createElement('td');sec.textContent=(e.start*60/project.bpm).toFixed(3);tr.append(sec);const td=document.createElement('td'),btn=document.createElement('button');btn.textContent='×';btn.setAttribute('aria-label',`Remove note ${i+1}`);btn.onclick=()=>tr.remove();td.append(btn);tr.append(td);body.append(tr);});}
function render({fields=true}={}){stop();$('grid').innerHTML=renderSVG(project,{mode,aesthetic});$('song-heading').textContent=project.title;$('summary').textContent=`${project.section}. ${(project.totalBeats*60/project.bpm).toFixed(2)} seconds at the score’s tempo.`;$('metrics').textContent=`${project.events.length} notes · ${project.totalBeats} beats · ${(project.totalBeats*60/project.bpm).toFixed(2)} s`;
 $('verification').textContent=project.provenance?.status==='score-read'?'Score-read arrangement · recording timing unverified':'Edited / imported events · unverified';$('source-note').textContent=project.provenance?.limitation||'No source verification recorded.';const link=$('source-link');let url;try{url=new URL(project.provenance?.source);if(!['https:','http:'].includes(url.protocol))url=null;}catch{}link.hidden=!url;link.href=url?.href||'#';link.textContent=(project.provenance?.label||'View melody source')+' ↗';
 const audit=projectToPMT(project);$('mapping-warning').hidden=!audit.warnings.length;$('mapping-warning').textContent=audit.warnings.join(' ');$('audit').replaceChildren();audit.events.forEach((e,i)=>{const row=document.createElement('div');row.textContent=`${i+1}. ${noteName(e.pitch)}: start ${(e.startError*60/project.bpm).toFixed(3)}s / end ${(e.endError*60/project.bpm).toFixed(3)}s${e.represented?'':' · OUT OF RANGE'}`;$('audit').append(row);});
 if(fields){for(const k of['title','section','bpm','totalBeats','beatsPerBar'])$(k).value=project[k];$('source').value=project.provenance?.source||'';for(const k of['key','scale','range','octave','canvasBeats','subdivision'])$(k).value=project.pmt[k];table();$('json').value=jsonText();}saveCurrent();showRevisions();}
function readFields(){const p=structuredClone(project);for(const k of['title','section'])p[k]=$(k).value;for(const k of['bpm','totalBeats','beatsPerBar'])p[k]=Number($(k).value);p.events=Array.from($('notes').rows,tr=>Object.fromEntries(Array.from(tr.querySelectorAll('input'),el=>[el.dataset.field,el.dataset.field==='pitch'?parsePitch(el.value):Number(el.value)])));for(const k of['key','scale','range','octave','canvasBeats','subdivision'])p.pmt[k]=k==='scale'?$(k).value:Number($(k).value);
 const changed=['title','section','bpm','totalBeats','beatsPerBar'].some(k=>p[k]!==project[k])||JSON.stringify(p.events)!==JSON.stringify(project.events)||$('source').value!==(project.provenance?.source||'');return validate(changed?draft(p):p);}
function commitFields(){project=readFields();render();message('Grid regenerated. Export JSON or save a revision to keep this version.');}
function download(content,type,name){const blob=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
const slug=()=>project.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70)||'melody';
function svgOptions(){return{mode,aesthetic};}
async function png(svg,name){const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob);try{const img=new Image();img.src=url;await img.decode();const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;c.getContext('2d').drawImage(img,0,0);const out=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!out)throw Error('PNG export failed. Try SVG.');download(out,'image/png',name);}finally{URL.revokeObjectURL(url);}}
function calibration(){const c={};for(const[id,key]of[['viewportWidth','viewportWidth'],['viewportHeight','viewportHeight'],['cx','x'],['cy','y'],['cw','width'],['ch','height']]){const n=Number($(id).value);if(!Number.isFinite(n)||n<0||n>6000)throw Error('Calibration values must be from 0 to 6000 pixels.');c[key]=n;}if(!c.width||!c.height||!c.viewportWidth||!c.viewportHeight||c.x+c.width>c.viewportWidth+1||c.y+c.height>c.viewportHeight+1)throw Error('The canvas must fit inside the viewport.');return c;}
function stop(){clearTimeout(playTimer);for(const o of voices)try{o.stop();}catch{}voices=[];$('listen').disabled=false;$('stop').disabled=true;}
async function listen(){stop();audioContext ||= new AudioContext();await audioContext.resume();const t=audioContext.currentTime+.1;for(const e of project.events){const o=audioContext.createOscillator(),gain=audioContext.createGain(),start=t+e.start*60/project.bpm,dur=e.duration*60/project.bpm;o.type='triangle';o.frequency.value=440*2**((e.pitch-69)/12);gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(.12,start+.008);gain.gain.setValueAtTime(.08,start+Math.max(.009,dur-.03));gain.gain.linearRampToValueAtTime(0,start+dur);o.connect(gain);gain.connect(audioContext.destination);o.start(start);o.stop(start+dur+.01);voices.push(o);} $('listen').disabled=true;$('stop').disabled=false;playTimer=setTimeout(stop,(project.totalBeats*60/project.bpm+.2)*1000);message('Playing the note events with a simple synthesized tone. This is not a comparison against a recording.');}
function encode(p){const bytes=new TextEncoder().encode(JSON.stringify(p));return btoa(Array.from(bytes,b=>String.fromCharCode(b)).join('')).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
function decode(s){if(s.length>120000)throw Error('Shared project is too large. Import JSON instead.');const text=atob(s.replace(/-/g,'+').replace(/_/g,'/'));return JSON.parse(new TextDecoder().decode(Uint8Array.from(text,c=>c.charCodeAt(0))));}
function imported(raw){const p=validate(raw);p.provenance={...p.provenance,status:'unverified',label:'Imported events — source claim not independently checked',limitation:'This project was imported. Its source information may help verification, but it has not been independently checked in this session.'};return p;}
function bind(){
 $('clean').onclick=()=>{aesthetic=false;$('clean').setAttribute('aria-pressed','true');$('art').setAttribute('aria-pressed','false');render({fields:false});};$('art').onclick=()=>{aesthetic=true;$('clean').setAttribute('aria-pressed','false');$('art').setAttribute('aria-pressed','true');render({fields:false});};$('layout').onchange=()=>{mode=$('layout').value;render({fields:false});};$('apply').onclick=safely(commitFields);
 $('reset').onclick=()=>{project=structuredClone(original);render();message('Original score-based study restored. Existing saved revisions are still available.');};
 $('add').onclick=()=>{const rows=Array.from($('notes').rows);const p=readFields();p.events.push({pitch:p.events.at(-1)?.pitch||60,start:Math.max(0,p.totalBeats-.5),duration:Math.min(.5,p.totalBeats)});project=validate(draft(p));render();message('Added a note at the end of the phrase. Edit its position and duration.');};
 $('apply-json').onclick=safely(()=>{const raw=JSON.parse($('json').value);project=imported(Array.isArray(raw)?{...project,events:raw}:raw);render();message('Imported events. Verify the source before treating this as an accurate transcription.');});
 for(const k of['key','scale','range','octave','canvasBeats','subdivision'])$(k).onchange=safely(commitFields);
 $('svg').onclick=safely(()=>download(renderSVG(project,svgOptions()),'image/svg+xml',`${slug()}-${mode}-${aesthetic?'aesthetic':'skeleton'}.svg`));$('png').onclick=safely(()=>png(renderSVG(project,svgOptions()),`${slug()}-${mode}-${aesthetic?'aesthetic':'skeleton'}.png`));
 $('background').onclick=safely(async()=>{const audit=projectToPMT(project);if(audit.events.some(e=>!e.represented)||project.totalBeats>project.pmt.canvasBeats)throw Error('Fix the pitch range or canvas length warning before exporting a PMT background.');await png(renderSVG(project,{mode:'pmt',aesthetic,calibration:calibration()}),`${slug()}-pmt-background.png`);message('Background exported for the calibrated viewport. Choose Stretch on PMT and keep that window size.');});
 $('listen').onclick=safely(listen);$('stop').onclick=stop;
 $('draw-it').onclick=safely(()=>{project=readFields();sessionStorage.setItem('singing-sketchbook-guide',JSON.stringify(project));stop();location.href='./paint.html';});
 $('export').onclick=safely(()=>{project=readFields();render();download(jsonText(),'application/json',slug()+'.json');});
 $('import').onchange=safely(async e=>{const file=e.target.files[0];if(!file)return;if(file.size>200000)throw Error('Use a project JSON smaller than 200 KB.');project=imported(JSON.parse(await file.text()));render();message('Project imported. Note events are unverified.');e.target.value='';});
 $('save').onclick=safely(()=>{project=readFields();const list=revisionList();list.unshift({at:new Date().toISOString(),project});localStorage.setItem(KEY+'-history',JSON.stringify(list.slice(0,20)));render();message('Saved a revision on this device. The last 20 revisions are kept. Export JSON for a portable copy.');});
 $('revisions').onchange=safely(()=>{if($('revisions').value==='')return;project=validate(revisionList()[Number($('revisions').value)].project);render();message('Saved device revision restored.');});
 $('share').onclick=safely(async()=>{project=readFields();render();const link=location.origin+location.pathname+'#project='+encode(project);try{await navigator.clipboard.writeText(link);message('Project link copied. It contains your current note data; anyone with the link can open it.');}catch{download(link,'text/plain',slug()+'-share-link.txt');message('Clipboard unavailable. Downloaded a text file containing the share link.');}});
 $('audio-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(audioURL)URL.revokeObjectURL(audioURL);audioURL=URL.createObjectURL(f);$('audio').src=audioURL;$('audio').hidden=false;};
 window.addEventListener('pagehide',stop);
}
try{original=validate(await(await fetch('./data/mia-sebastian.json')).json());project=structuredClone(original);let loaded=false;if(location.hash.startsWith('#project=')){project=imported(decode(location.hash.slice(9)));loaded=true;}else{try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved){project=validate(saved);loaded=true;}}catch{}}bind();render();if(loaded)message('Loaded your saved or shared project. “Load original study” returns to the source-read example.');}catch(e){message('Could not open project: '+e.message,true);}
